begin;
do $$begin if current_setting('app.environment',true)is distinct from 'test'then raise exception 'test environment required';end if;end$$;
insert into auth.users(id,email)select ('a8100000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'content-'||i||'@example.invalid'from generate_series(1,5)i;
insert into public.workspaces(id,name,slug)values('b8100000-0000-4000-8000-000000000001','Content Synthetic','content-synthetic'),('b8100000-0000-4000-8000-000000000002','Content Foreign','content-foreign');
insert into public.workspace_members(workspace_id,user_id,role)select 'b8100000-0000-4000-8000-000000000001',('a8100000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,(array['owner','admin','member','viewer'])[i]from generate_series(1,4)i;
insert into public.workspace_members(workspace_id,user_id,role)values('b8100000-0000-4000-8000-000000000002','a8100000-0000-4000-8000-000000000005','owner');
insert into public.customers(id,workspace_id,account_kind,legal_name)values('c8100000-0000-4000-8000-000000000001','b8100000-0000-4000-8000-000000000001','legal_entity','Content Synthetic Customer'),('c8100000-0000-4000-8000-000000000002','b8100000-0000-4000-8000-000000000002','legal_entity','Foreign Content Customer');
create function pg_temp.dc_assert(ok boolean)returns void language plpgsql as $$begin if ok is not true then raise exception 'content assertion';end if;end$$;
create function pg_temp.dc_deny(q text,code text)returns void language plpgsql as $$declare actual text;msg text;begin begin execute q;exception when others then actual:=sqlstate;msg:=sqlerrm;end;if actual is distinct from code then raise exception 'content expected %,got %: %',code,actual,msg;end if;end$$;
create temp table dc_saved(id uuid,input jsonb,receipt jsonb,finalize jsonb,ticket jsonb);grant all on dc_saved to authenticated;
set local role authenticated;select set_config('request.jwt.claim.sub','a8100000-0000-4000-8000-000000000001',true);
do $$declare w uuid:='b8100000-0000-4000-8000-000000000001';i jsonb;r jsonb;begin
 i:='{"command_id":"98100000-0000-4000-8000-000000000001","target_kind":"customer","target_id":"c8100000-0000-4000-8000-000000000001","document_kind":"general","media_type":"application/pdf","size_bytes":32,"file_name":"Synthetic.pdf"}';
 r:=public.document_content_v1_request_upload(w,i);perform pg_temp.dc_assert(r->>'status'='pending'and r->>'version'='1'and not r?'storage_path'and not r?'object_ref');perform pg_temp.dc_assert(r=public.document_content_v1_request_upload(w,i));
 insert into dc_saved values((r->>'id')::uuid,i,r,jsonb_build_object('command_id','98100000-0000-4000-8000-000000000002','id',r->>'id','expected_version',1),null);
 perform pg_temp.dc_deny(format('select public.document_content_v1_request_upload(%L,%L)',w,(i||'{"size_bytes":33}')::text),'40001');
 perform pg_temp.dc_deny(format('select public.document_content_v1_request_upload(%L,%L)',w,(i||'{"storage_path":"arbitrary"}')::text),'22023');
 perform pg_temp.dc_deny(format('select public.document_content_v1_request_upload(%L,%L)',w,(i||jsonb_build_object('command_id',gen_random_uuid(),'target_id','c8100000-0000-4000-8000-000000000002'))::text),'P0002');
 perform pg_temp.dc_deny(format('select public.document_content_v1_finalize_upload(%L,%L)',w,(select finalize::text from dc_saved)),'22023');
 perform pg_temp.dc_assert(public.document_v1_get_metadata(w,jsonb_build_object('id',r->>'id'))is null);
 perform pg_temp.dc_deny(format('select public.document_content_v1_request_download(%L,%L)',w,jsonb_build_object('command_id',gen_random_uuid(),'id',r->>'id','expected_version',1)::text),'42501');
end$$;
reset role;
select pg_temp.dc_assert((select count(*)from public.documents d join dc_saved s on s.id=d.id where d.status='pending'and d.sha256_hex is null)=1);
-- Exact pending object insertion is authorized; arbitrary, foreign and replacement paths are closed.
set local role authenticated;select set_config('request.jwt.claim.sub','a8100000-0000-4000-8000-000000000001',true);
do $$declare s record;m jsonb;path text;begin
 select *into s from dc_saved;m:=public.document_content_v1_manifest('b8100000-0000-4000-8000-000000000001',jsonb_build_object('id',s.id));path:='b8100000-0000-4000-8000-000000000001/documents/'||s.id::text||'/'||(m->>'object_ref');
 insert into storage.objects(id,bucket_id,name,metadata)values(gen_random_uuid(),'telecom-documents',path,'{"mimetype":"application/pdf"}');
 perform pg_temp.dc_assert((select count(*)from storage.objects where name=path)=1);
 perform pg_temp.dc_deny(format('insert into storage.objects(id,bucket_id,name)values(gen_random_uuid(),''telecom-documents'',%L)',path||'/forged'),'42501');
 perform pg_temp.dc_deny(format('select public.document_content_v1_finalize_upload(%L,%L)','b8100000-0000-4000-8000-000000000001',s.finalize::text),'22023');
end$$;
select set_config('request.jwt.claim.sub','a8100000-0000-4000-8000-000000000002',true);
select pg_temp.dc_assert((select count(*)from storage.objects where bucket_id='telecom-documents')=0);
select pg_temp.dc_deny(format('select public.document_content_v1_manifest(%L,%L)','b8100000-0000-4000-8000-000000000001',(select jsonb_build_object('id',id)::text from dc_saved)),'42501');
reset role;
update storage.objects set metadata='{"size":31,"mimetype":"application/pdf"}'where name=(select d.storage_path from public.documents d join dc_saved s on d.id=s.id);
set local role authenticated;select set_config('request.jwt.claim.sub','a8100000-0000-4000-8000-000000000001',true);
select pg_temp.dc_deny(format('select public.document_content_v1_finalize_upload(%L,%L)','b8100000-0000-4000-8000-000000000001',(select finalize::text from dc_saved)),'22023');
reset role;update storage.objects set metadata='{"size":32,"mimetype":"application/pdf"}'where name=(select d.storage_path from public.documents d join dc_saved s on d.id=s.id);
set local role authenticated;select set_config('request.jwt.claim.sub','a8100000-0000-4000-8000-000000000001',true);
do $$declare s record;r jsonb;t jsonb;w uuid:='b8100000-0000-4000-8000-000000000001';begin
 select *into s from dc_saved;r:=public.document_content_v1_finalize_upload(w,s.finalize);perform pg_temp.dc_assert(r->>'status'='active'and r->>'version'='2'and r=public.document_content_v1_finalize_upload(w,s.finalize));
 t:=jsonb_build_object('command_id',gen_random_uuid(),'id',s.id,'expected_version',2);r:=public.document_content_v1_request_download(w,t);perform pg_temp.dc_assert(r=public.document_content_v1_request_download(w,t)and r?'ticket_id'and r->>'version'='2');update dc_saved set ticket=r;
 perform pg_temp.dc_assert(public.document_content_v1_manifest(w,jsonb_build_object('id',s.id,'ticket_id',r->>'ticket_id'))->>'id'=s.id::text);
 perform public.document_v1_archive(w,jsonb_build_object('command_id',gen_random_uuid(),'id',s.id,'expected_version',2));
 perform pg_temp.dc_deny(format('select public.document_content_v1_manifest(%L,%L)',w,jsonb_build_object('id',s.id,'ticket_id',r->>'ticket_id')::text),'42501');
 perform pg_temp.dc_assert((select count(*)from storage.objects where bucket_id='telecom-documents')=0);
 perform pg_temp.dc_deny(format('select public.document_content_v1_request_download(%L,%L)',w,jsonb_build_object('command_id',gen_random_uuid(),'id',s.id,'expected_version',3)::text),'42501');
 perform public.document_v1_restore(w,jsonb_build_object('command_id',gen_random_uuid(),'id',s.id,'expected_version',3));
end$$;
reset role;
update public.document_download_tickets set expires_at=statement_timestamp()-interval '1 second'where id=(select(ticket->>'ticket_id')::uuid from dc_saved);
set local role authenticated;select set_config('request.jwt.claim.sub','a8100000-0000-4000-8000-000000000001',true);
select pg_temp.dc_deny(format('select public.document_content_v1_manifest(%L,%L)','b8100000-0000-4000-8000-000000000001',(select jsonb_build_object('id',id,'ticket_id',ticket->>'ticket_id')::text from dc_saved)),'42501');
select set_config('request.jwt.claim.sub','a8100000-0000-4000-8000-000000000003',true);
select pg_temp.dc_deny(format('select public.document_content_v1_request_upload(%L,%L)','b8100000-0000-4000-8000-000000000001',(select input::text from dc_saved)),'42501');
select set_config('request.jwt.claim.sub','a8100000-0000-4000-8000-000000000004',true);
select pg_temp.dc_deny(format('select public.document_content_v1_request_upload(%L,%L)','b8100000-0000-4000-8000-000000000001',(select input::text from dc_saved)),'42501');
select set_config('request.jwt.claim.sub','a8100000-0000-4000-8000-000000000005',true);
select pg_temp.dc_deny(format('select public.document_content_v1_request_upload(%L,%L)','b8100000-0000-4000-8000-000000000001',(select input::text from dc_saved)),'42501');
reset role;
update public.workspace_members set status='suspended'where user_id='a8100000-0000-4000-8000-000000000001';
set local role authenticated;select set_config('request.jwt.claim.sub','a8100000-0000-4000-8000-000000000001',true);
select pg_temp.dc_deny(format('select public.document_content_v1_request_upload(%L,%L)','b8100000-0000-4000-8000-000000000001',(select input::text from dc_saved)),'42501');
reset role;
-- Audit failure rolls back pending metadata, intent and command together.
update public.workspace_members set status='active'where user_id='a8100000-0000-4000-8000-000000000001';
create function pg_temp.dc_break()returns trigger language plpgsql as $$begin raise exception using errcode='P0001',message='forced content audit failure';end$$;
create trigger dc_break before insert on public.product_audit_events for each row execute function pg_temp.dc_break();
set local role authenticated;select set_config('request.jwt.claim.sub','a8100000-0000-4000-8000-000000000001',true);
select pg_temp.dc_deny(format('select public.document_content_v1_request_upload(%L,%L)','b8100000-0000-4000-8000-000000000001',(select(input||'{"command_id":"98100000-0000-4000-8000-000000000099"}')::text from dc_saved)),'P0001');
reset role;
select pg_temp.dc_assert((select count(*)from public.documents where workspace_id='b8100000-0000-4000-8000-000000000001')=1);
select pg_temp.dc_assert(not exists(select 1 from public.product_commands where command_id='98100000-0000-4000-8000-000000000099'));
-- Failed finalization never left a command reservation or promoted an orphan.
select pg_temp.dc_assert((select count(*)from public.product_commands where command_id='98100000-0000-4000-8000-000000000002')=1);
rollback;
